        document.querySelectorAll('.tab-panel').forEach(content => content.classList.remove('active'));
        if (tabElement) tabElement.classList.add('active');
        const targetPanel = document.getElementById('tab-content-' + tabName);
        if (targetPanel) targetPanel.classList.add('active');
    }

    function copyActionToClipboard(button, template) {
        if (!navigator.clipboard) {
            alert('您的浏览器不支持剪贴板API，无法复制。');
            return;
        }
        const currentTarget = SafeGetValue(characterData, 'love_interest.current_target', '当前目标');
        const finalMessage = template.replace('{{currentTarget}}', currentTarget);
        
        navigator.clipboard.writeText(finalMessage).then(() => {
            const originalText = button.innerText;
            button.innerText = '已复制!';
            setTimeout(() => {
                button.innerText = originalText;
            }, 1500);
        }).catch(err => {
            console.error('无法复制文本: ', err);
            alert('复制失败，请手动复制。');
        });
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<div class='error-tip'>无法加载状态数据 (messages empty)</div>";
                return;
            }
            const gameData = messages[0].data;
            characterData = gameData.stat_data;
            if (!characterData) {
                document.getElementById('status-card').innerHTML = "<div class='error-tip'>无法加载状态数据 (characterData missing)</div>";
                return;
            }

            document.getElementById('world-time').innerText = SafeGetValue(characterData, 'world.time');
            document.getElementById('player-location').innerText = SafeGetValue(characterData, 'player.current_location');
            document.getElementById('world-major_event').innerText = SafeGetValue(characterData, 'world.major_event');

            updateProgressBar('player-influence-bar', 'player-influence', SafeGetValue(characterData, 'player.influence', 0), 0, 1000);
            updateProgressBar('player-martial_arts-bar', 'player-martial_arts', SafeGetValue(characterData, 'player.skills.martial_arts', 0), 0, 100);
            updateProgressBar('rivalry-xiang_shaolong-bar', 'rivalry-xiang_shaolong', SafeGetValue(characterData, 'rivalry.xiang_shaolong', 0), -100, 100);

            const women = [
                { key: 'mei_can_niang', color: 'var(--accent-rose)' },
                { key: 'zhao_zhi', color: 'var(--accent-teal)' },
                { key: 'ji_yanran', color: 'var(--accent-lilac)' },
                { key: 'qin_qing', color: 'var(--accent-gold)' }
            ];
            women.forEach(woman => {
                const stage = SafeGetValue(characterData, `love_interest.${woman.key}.stage`);
                const tab = document.getElementById(`tab-${woman.key}`);
                if (stage !== '未解锁' && stage !== 'N/A') {
                    if(tab) tab.style.display = 'block';
                    updateProgressBar(`${woman.key}-favor-bar`, `${woman.key}-favor`, SafeGetValue(characterData, `love_interest.${woman.key}.favor`, 0), -100, 100, woman.color);
                    updateProgressBar(`${woman.key}-lewd-bar`, `${woman.key}-lewd`, SafeGetValue(characterData, `love_interest.${woman.key}.lewd`, 0), 0, 100, '#e74c3c');
                    const stageElem = document.getElementById(`${woman.key}-stage`);
                    if(stageElem) stageElem.innerText = stage;
                } else {
                    if(tab) tab.style.display = 'none';
                }
            });

            const activeTab = document.querySelector('.tab-button.active');
            if (activeTab && activeTab.style.display === 'none') {
                switchTab('overview', document.querySelector('[data-tab="overview"]'));
            }

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<div class='error-tip'>状态栏加载出错: ${error.message}</div>`;
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
